CREATE TEMP TABLE demo_ops(account_external text,external_id text,booked_at timestamptz,direction text,category text,amount numeric,description text) ON COMMIT DROP;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM alfa.users WHERE email='bank@example.test' AND role='BANK_EMPLOYEE' AND active) THEN RAISE EXCEPTION 'Bank employee missing'; END IF; END $$;
SELECT a.id,o.external_id,o.booked_at,o.direction,o.category,o.amount,o.description,u.id
FROM demo_ops o JOIN alfa.bank_accounts a ON a.external_id=o.account_external
